import{_ as n,o as i,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Kịch bản Kiểm thử (Test Cases) — FR 3.6.15: Apply Watermark to Material","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-15-apply-watermark/test.md","filePath":"feature/content-task-workflow/3-6-15-apply-watermark/test.md"}'),e={name:"feature/content-task-workflow/3-6-15-apply-watermark/test.md"};function l(r,t,h,c,g,s){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="kich-ban-kiem-thu-test-cases-—-fr-3-6-15-apply-watermark-to-material" tabindex="-1">Kịch bản Kiểm thử (Test Cases) — FR 3.6.15: Apply Watermark to Material <a class="header-anchor" href="#kich-ban-kiem-thu-test-cases-—-fr-3-6-15-apply-watermark-to-material" aria-label="Permalink to &quot;Kịch bản Kiểm thử (Test Cases) — FR 3.6.15: Apply Watermark to Material&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Thông tin</th><th>Chi tiết</th></tr></thead><tbody><tr><td><strong>Mã chức năng</strong></td><td><strong>FR 3.6.15 (DA-E51-06e)</strong></td></tr><tr><td><strong>Tài liệu tham chiếu</strong></td><td><a href="./spec.html">spec.md</a> | <a href="./plan.html">plan.md</a></td></tr><tr><td><strong>Phân hệ</strong></td><td><code>brandhub-business-service</code>, <code>brandhub-web-dashboard</code></td></tr></tbody></table><hr><h2 id="_1-kiem-thu-tieu-chi-chap-nhan-acceptance-criteria-test-cases" tabindex="-1">1. Kiểm thử Tiêu chí Chấp nhận (Acceptance Criteria Test Cases) <a class="header-anchor" href="#_1-kiem-thu-tieu-chi-chap-nhan-acceptance-criteria-test-cases" aria-label="Permalink to &quot;1. Kiểm thử Tiêu chí Chấp nhận (Acceptance Criteria Test Cases)&quot;">​</a></h2><h3 id="tc-ac-01-kiem-tra-tinh-nang-đong-dau-co-ban-voi-9-vi-tri-luoi-single-mode" tabindex="-1">TC-AC-01: Kiểm tra tính năng đóng dấu cơ bản với 9 vị trí lưới (Single Mode) <a class="header-anchor" href="#tc-ac-01-kiem-tra-tinh-nang-đong-dau-co-ban-voi-9-vi-tri-luoi-single-mode" aria-label="Permalink to &quot;TC-AC-01: Kiểm tra tính năng đóng dấu cơ bản với 9 vị trí lưới (Single Mode)&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Đã có 1 Material ảnh dạng <code>RETOUCHED</code> và Brand Collection của Workspace có ít nhất 1 Logo hợp lệ (PNG trong suốt).</li><li><strong>Các bước thực hiện</strong>: <ol><li>Creator mở màn hình Material hoặc Task Detail, bấm icon &quot;Đóng dấu bản quyền&quot; (Apply Watermark).</li><li>Chọn Logo từ Brand Collection.</li><li>Lần lượt bấm thử 9 vị trí trên lưới: <code>TOP_LEFT</code>, <code>CENTER</code>, <code>BOTTOM_RIGHT</code>...</li><li>Quan sát khung Live Preview Canvas.</li><li>Chọn vị trí <code>BOTTOM_RIGHT</code>, chỉnh Opacity = 80%, Scale = 15%, bấm <strong>&quot;Áp dụng &amp; Tạo bản mới&quot;</strong>.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Live Preview cập nhật tức thì vị trí logo tương ứng mỗi khi click chọn.</li><li>API trả về <code>201 Created</code> kèm thông tin Material mới có <code>type = WATERMARKED</code>.</li><li>Ảnh xuất ra có logo nằm chuẩn tại góc dưới bên phải, cách lề an toàn ~3%, độ trong suốt 80%.</li><li>Ảnh gốc không hề bị thay đổi hay ghi đè.</li></ul></li></ul><h3 id="tc-ac-02-kiem-tra-che-đo-luoi-bao-ve-ban-quyen-tiled-draft-protection-mode" tabindex="-1">TC-AC-02: Kiểm tra chế độ Lưới bảo vệ bản quyền (Tiled Draft Protection Mode) <a class="header-anchor" href="#tc-ac-02-kiem-tra-che-đo-luoi-bao-ve-ban-quyen-tiled-draft-protection-mode" aria-label="Permalink to &quot;TC-AC-02: Kiểm tra chế độ Lưới bảo vệ bản quyền (Tiled Draft Protection Mode)&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Đang mở modal Watermark Studio.</li><li><strong>Các bước thực hiện</strong>: <ol><li>Chọn Logo thương hiệu.</li><li>Bật chế độ &quot;Lưới bảo vệ bản quyền (Tiled)&quot;.</li><li>Chỉnh Opacity = 20%, bấm &quot;Áp dụng &amp; Tạo bản mới&quot;.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Live Preview và file kết quả hiển thị logo lặp lại đều đặn dạng lưới nghiêng -45° phủ toàn bộ diện tích ảnh với độ mờ nhẹ (20%), thích hợp gửi demo cho khách hàng duyệt bản nháp.</li></ul></li></ul><h3 id="tc-ac-03-kiem-tra-tinh-bao-toan-kenh-alpha-alpha-transparency" tabindex="-1">TC-AC-03: Kiểm tra tính bảo toàn kênh Alpha (Alpha Transparency) <a class="header-anchor" href="#tc-ac-03-kiem-tra-tinh-bao-toan-kenh-alpha-alpha-transparency" aria-label="Permalink to &quot;TC-AC-03: Kiểm tra tính bảo toàn kênh Alpha (Alpha Transparency)&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Logo là file PNG có nền trong suốt.</li><li><strong>Các bước thực hiện</strong>: Đóng dấu logo lên một bức ảnh có nhiều mảng màu tối và sáng.</li><li><strong>Kết quả mong đợi</strong>: <ul><li>Logo hiển thị mượt mà không có viền đen, răng cưa hay nền trắng bao quanh. Kênh Alpha của logo kết hợp hoàn hảo với các điểm ảnh nền.</li></ul></li></ul><hr><h2 id="_2-kiem-thu-truong-hop-bien-ngoai-le-edge-cases-negative-tests" tabindex="-1">2. Kiểm thử Trường hợp Biên &amp; Ngoại lệ (Edge Cases &amp; Negative Tests) <a class="header-anchor" href="#_2-kiem-thu-truong-hop-bien-ngoai-le-edge-cases-negative-tests" aria-label="Permalink to &quot;2. Kiểm thử Trường hợp Biên &amp; Ngoại lệ (Edge Cases &amp; Negative Tests)&quot;">​</a></h2><h3 id="tc-neg-01-workspace-chua-co-logo-trong-brand-collection" tabindex="-1">TC-NEG-01: Workspace chưa có Logo trong Brand Collection <a class="header-anchor" href="#tc-neg-01-workspace-chua-co-logo-trong-brand-collection" aria-label="Permalink to &quot;TC-NEG-01: Workspace chưa có Logo trong Brand Collection&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Tạo một Workspace mới hoàn toàn mà Client chưa upload bất kỳ Logo nào vào Brand Collection.</li><li><strong>Các bước thực hiện</strong>: <ol><li>Mở một Material trong Workspace này và click &quot;Đóng dấu bản quyền&quot;.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Modal hiển thị thông báo cảnh báo rõ ràng: <em>&quot;Chưa có logo trong Brand Collection của Client...&quot;</em>.</li><li>Nút &quot;Áp dụng&quot; bị vô hiệu hóa (disabled).</li><li>Nếu cố tình gửi API <code>POST .../watermark</code> với <code>logoAssetId</code> rỗng -&gt; Backend trả về <code>400 LOGO_NOT_FOUND</code>.</li></ul></li></ul><h3 id="tc-neg-02-co-tinh-đong-dau-len-material-khong-phai-la-anh-video-pdf" tabindex="-1">TC-NEG-02: Cố tình đóng dấu lên Material không phải là ảnh (Video / PDF) <a class="header-anchor" href="#tc-neg-02-co-tinh-đong-dau-len-material-khong-phai-la-anh-video-pdf" aria-label="Permalink to &quot;TC-NEG-02: Cố tình đóng dấu lên Material không phải là ảnh (Video / PDF)&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Material có mimeType là <code>video/mp4</code> hoặc <code>application/pdf</code>.</li><li><strong>Các bước thực hiện</strong>: <ol><li>Gửi request <code>POST /api/v1/workspaces/{id}/materials/{videoMaterialId}/watermark</code>.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Backend chặn ngay lập tức, trả về <code>400 INVALID_MATERIAL_TYPE</code>.</li></ul></li></ul><h3 id="tc-neg-03-anh-goc-đo-phan-giai-cao-4k-8k-gt-10mb" tabindex="-1">TC-NEG-03: Ảnh gốc độ phân giải cao (4K / 8K, &gt; 10MB) <a class="header-anchor" href="#tc-neg-03-anh-goc-đo-phan-giai-cao-4k-8k-gt-10mb" aria-label="Permalink to &quot;TC-NEG-03: Ảnh gốc độ phân giải cao (4K / 8K, &amp;gt; 10MB)&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: Material gốc là ảnh 4K (3840x2160, dung lượng ~12MB).</li><li><strong>Các bước thực hiện</strong>: <ol><li>Mở modal Watermark Studio trên Frontend.</li><li>Kéo thanh trượt Opacity và Scale liên tục.</li><li>Bấm Apply Watermark.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Live Preview trên Canvas không bị đơ, giật lag hay treo trình duyệt (nhờ sử dụng preview scale).</li><li>Backend xử lý thành công không bị tràn bộ nhớ Java Heap (OutOfMemoryError), ảnh kết quả giữ nguyên độ phân giải 3840x2160 sắc nét.</li></ul></li></ul><h3 id="tc-neg-04-quyen-truy-cap-khong-hop-le" tabindex="-1">TC-NEG-04: Quyền truy cập không hợp lệ <a class="header-anchor" href="#tc-neg-04-quyen-truy-cap-khong-hop-le" aria-label="Permalink to &quot;TC-NEG-04: Quyền truy cập không hợp lệ&quot;">​</a></h3><ul><li><strong>Tiền điều kiện</strong>: User không thuộc Workspace hoặc tài khoản đã bị vô hiệu hóa.</li><li><strong>Các bước thực hiện</strong>: Gửi request watermark.</li><li><strong>Kết quả mong đợi</strong>: Trả về <code>403 FORBIDDEN_WORKSPACE_ACCESS</code>.</li></ul><hr><h2 id="_3-kiem-thu-giao-dien-đa-ngon-ngu-sang-toi-i18n-theme-tests" tabindex="-1">3. Kiểm thử Giao diện: Đa ngôn ngữ &amp; Sáng/Tối (i18n &amp; Theme Tests) <a class="header-anchor" href="#_3-kiem-thu-giao-dien-đa-ngon-ngu-sang-toi-i18n-theme-tests" aria-label="Permalink to &quot;3. Kiểm thử Giao diện: Đa ngôn ngữ &amp; Sáng/Tối (i18n &amp; Theme Tests)&quot;">​</a></h2><h3 id="tc-ui-01-kiem-tra-đa-ngon-ngu-vietnamese-english" tabindex="-1">TC-UI-01: Kiểm tra Đa ngôn ngữ (Vietnamese &amp; English) <a class="header-anchor" href="#tc-ui-01-kiem-tra-đa-ngon-ngu-vietnamese-english" aria-label="Permalink to &quot;TC-UI-01: Kiểm tra Đa ngôn ngữ (Vietnamese &amp; English)&quot;">​</a></h3><ul><li><strong>Các bước thực hiện</strong>: <ol><li>Đổi ngôn ngữ hệ thống sang Tiếng Việt -&gt; Mở Watermark Studio Modal.</li><li>Đổi ngôn ngữ hệ thống sang Tiếng Anh -&gt; Mở lại Watermark Studio Modal.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>100% tiêu đề, nhãn thanh trượt, tooltip, nút bấm, thông báo toast chuyển đổi đúng theo từ điển i18n (<code>vi.json</code> và <code>en.json</code>).</li><li>Tuyệt đối không có chuỗi nào hiển thị dạng mã raw (như <code>materials.watermark.title</code>) hoặc bị hardcode tiếng Việt trong giao diện tiếng Anh.</li></ul></li></ul><h3 id="tc-ui-02-kiem-tra-giao-dien-sang-toi-light-dark-mode" tabindex="-1">TC-UI-02: Kiểm tra Giao diện Sáng / Tối (Light &amp; Dark Mode) <a class="header-anchor" href="#tc-ui-02-kiem-tra-giao-dien-sang-toi-light-dark-mode" aria-label="Permalink to &quot;TC-UI-02: Kiểm tra Giao diện Sáng / Tối (Light &amp; Dark Mode)&quot;">​</a></h3><ul><li><strong>Các bước thực hiện</strong>: <ol><li>Bật Dark Mode trong cài đặt hệ thống.</li><li>Mở Watermark Studio Modal và thao tác toàn bộ quy trình.</li></ol></li><li><strong>Kết quả mong đợi</strong>: <ul><li>Nền modal chuyển sang tông màu tối dịu mắt (<code>bg-neutral-900</code>).</li><li>Vùng canvas preview hiển thị nền caro tối (checkerboard-dark) tương phản tốt với ảnh.</li><li>Các chữ, nhãn, thanh trượt hiển thị rõ ràng, không bị chìm màu hay mất nét viền.</li></ul></li></ul>',26)])])}const m=n(e,[["render",l]]);export{u as __pageData,m as default};
